// lib/python/bytes_repr.mjs
//
// Python `repr()` formatters, driven by explicit lookup tables that map 1:1 onto
// the MEASURED ground-truth table in the porting spec. Nothing here is clever:
// every rule is a table row you can read next to the spec.
//
// Two formatters live here because they share one piece of machinery -- Python's
// quote-selection rule -- and nothing else:
//   * pyBytesRepr(byteArray) -> repr() of a `bytes` object   (used by print(data))
//   * pyStrRepr(text)        -> repr() of a `str` object     (used by argparse's
//                               "invalid int value: %r" message)
//
// The built byte sequence is a PLAIN Array of integers 0..255. No binary-view
// APIs, no typed arrays, no Buffer.

// ---------------------------------------------------------------------------
// Quote selection (MEASURED)
// ---------------------------------------------------------------------------
// Python picks the quote character before it escapes anything:
//
//   contains '  | contains "  | quote used | notes
//   -----------+--------------+------------+---------------------------------
//   no         | no           | '          | nothing special
//   no         | yes          | '          | the " stays literal
//   yes        | no           | "          | the ' stays literal (b"'A")
//   yes        | yes          | '          | the ' is escaped as \' (b'\'"')
//
// Equivalently: use " only when ' is present and " is absent. Then escape any
// occurrence of whatever quote was chosen.
export const QUOTE_RULES = [
  { hasSingle: false, hasDouble: false, quote: "'" },
  { hasSingle: false, hasDouble: true, quote: "'" },
  { hasSingle: true, hasDouble: false, quote: '"' },
  { hasSingle: true, hasDouble: true, quote: "'" },
];

export const SINGLE_QUOTE_BYTE = 0x27; // '
export const DOUBLE_QUOTE_BYTE = 0x22; // "

/**
 * Look the quote character up in QUOTE_RULES instead of re-deriving it.
 * @param {boolean} hasSingle
 * @param {boolean} hasDouble
 * @returns {string} either "'" or '"'
 */
export function chooseQuote(hasSingle, hasDouble) {
  for (const rule of QUOTE_RULES) {
    if (rule.hasSingle === hasSingle && rule.hasDouble === hasDouble) {
      return rule.quote;
    }
  }
  // Unreachable: the table covers all four boolean combinations.
  return "'";
}

// ---------------------------------------------------------------------------
// Byte escape table (MEASURED)
// ---------------------------------------------------------------------------
// Short named escapes. These win over the printable-ASCII range, which matters
// for 0x5c: a backslash byte is inside 0x20..0x7e but must double itself.
export const BYTE_SHORT_ESCAPES = [
  [0x09, '\\t'], // horizontal tab
  [0x0a, '\\n'], // line feed
  [0x0d, '\\r'], // carriage return
  [0x5c, '\\\\'], // backslash -> two backslash characters
];

// Bytes in this inclusive range print as their literal ASCII character.
export const PRINTABLE_BYTE_MIN = 0x20; // space
export const PRINTABLE_BYTE_MAX = 0x7e; // tilde

const LOWER_HEX_DIGITS = '0123456789abcdef';

/**
 * Two lowercase hex digits, always padded. Used for \xNN escapes.
 * @param {number} value 0..255
 * @returns {string}
 */
export function lowerHex2(value) {
  return LOWER_HEX_DIGITS[(value >> 4) & 0x0f] + LOWER_HEX_DIGITS[value & 0x0f];
}

/**
 * BYTE_ESCAPE_TABLE[b] is the exact text Python emits for byte b, ignoring the
 * active-quote override. Built once from the three rules above so the table can
 * be dumped and eyeballed against the spec (see dumpByteEscapeTable).
 * @type {string[]}
 */
export const BYTE_ESCAPE_TABLE = (() => {
  const shortEscapes = new Map(BYTE_SHORT_ESCAPES);
  const table = [];
  for (let b = 0; b <= 0xff; b += 1) {
    if (shortEscapes.has(b)) {
      table.push(shortEscapes.get(b));
    } else if (b >= PRINTABLE_BYTE_MIN && b <= PRINTABLE_BYTE_MAX) {
      table.push(String.fromCharCode(b));
    } else {
      table.push('\\x' + lowerHex2(b));
    }
  }
  return table;
})();

/**
 * Audit helper: returns "NN=<escape>" for every byte, so the generated table can
 * be diffed against the measured table by hand.
 * @returns {string[]}
 */
export function dumpByteEscapeTable() {
  return BYTE_ESCAPE_TABLE.map((text, b) => `${lowerHex2(b)}=${text}`);
}

/**
 * Python's repr() of a bytes object, e.g. [0x10, 0xa1] -> b'\x10\xa1'.
 * @param {number[]} byteArray plain array of integers 0..255
 * @returns {string}
 */
export function pyBytesRepr(byteArray) {
  let hasSingle = false;
  let hasDouble = false;
  for (const b of byteArray) {
    if (b === SINGLE_QUOTE_BYTE) hasSingle = true;
    else if (b === DOUBLE_QUOTE_BYTE) hasDouble = true;
  }

  const quote = chooseQuote(hasSingle, hasDouble);
  const activeQuoteByte = quote === "'" ? SINGLE_QUOTE_BYTE : DOUBLE_QUOTE_BYTE;

  let body = '';
  for (const b of byteArray) {
    body += b === activeQuoteByte ? '\\' + quote : BYTE_ESCAPE_TABLE[b];
  }
  return 'b' + quote + body + quote;
}

// ---------------------------------------------------------------------------
// str repr (MEASURED via argparse's "invalid int value: %r")
// ---------------------------------------------------------------------------
// Python's str repr keeps any *printable* character literally, where printable
// means "not in Unicode category Other (C*) or Separator (Z*)", with ASCII space
// (U+0020) explicitly excepted. Measured confirmations:
//   '​16'  (U+200B ZERO WIDTH SPACE is Cf -> escaped)
//   '　'    (U+3000 IDEOGRAPHIC SPACE is Zs -> escaped)
//   '٣x'        (U+0663 is Nd -> literal)
//   '１２x'      (U+FF11/FF12 are Nd -> literal)
//   'é'         (U+00E9 is Ll -> literal)
const NON_PRINTABLE_RE = /[\p{C}\p{Z}]/u;

// Short named escapes for str, same three control characters as bytes.
export const STR_SHORT_ESCAPES = new Map([
  ['\t', '\\t'],
  ['\n', '\\n'],
  ['\r', '\\r'],
  ['\\', '\\\\'],
]);

/**
 * Python's str.isprintable() for a single character.
 * @param {string} ch one code point
 * @returns {boolean}
 */
export function pyIsPrintable(ch) {
  if (ch === ' ') return true; // ASCII space is the documented exception
  return !NON_PRINTABLE_RE.test(ch);
}

/**
 * Escape width table for non-printable code points (Python uses lowercase hex):
 *   cp < 0x100    -> \xNN
 *   cp < 0x10000  -> \uNNNN
 *   otherwise     -> \UNNNNNNNN
 */
export const STR_ESCAPE_WIDTHS = [
  { limit: 0x100, prefix: '\\x', digits: 2 },
  { limit: 0x10000, prefix: '\\u', digits: 4 },
  { limit: 0x110000, prefix: '\\U', digits: 8 },
];

function escapeCodePoint(cp) {
  for (const row of STR_ESCAPE_WIDTHS) {
    if (cp < row.limit) {
      return row.prefix + cp.toString(16).padStart(row.digits, '0');
    }
  }
  return '\\U' + cp.toString(16).padStart(8, '0');
}

/**
 * Python's repr() of a str object.
 * @param {string} text
 * @returns {string}
 */
export function pyStrRepr(text) {
  const chars = Array.from(text);
  const quote = chooseQuote(chars.includes("'"), chars.includes('"'));

  let body = '';
  for (const ch of chars) {
    if (ch === quote) {
      body += '\\' + quote;
    } else if (STR_SHORT_ESCAPES.has(ch)) {
      body += STR_SHORT_ESCAPES.get(ch);
    } else if (pyIsPrintable(ch)) {
      body += ch;
    } else {
      body += escapeCodePoint(ch.codePointAt(0));
    }
  }
  return quote + body + quote;
}

// lib/python/int_parse.mjs
//
// Python's int(str) conversion semantics, expressed as data tables.
//
// The result is carried as a BigInt because the spec requires the *exact*
// original magnitude to survive into the construct error message:
//   --a 99999999999999999999 -> "given value 99999999999999999999"
// A JS double would round that to 100000000000000000000.

// ---------------------------------------------------------------------------
// Whitespace table (MEASURED: int() strips ASCII and Unicode whitespace)
// ---------------------------------------------------------------------------
// CPython's int() skips code points for which Py_UNICODE_ISSPACE is true. That is
// exactly the set below. Measured confirmations:
//   "  16  " -> 16 ; "\t42\n" -> 42 ; " 16" -> 16 ; "　16" -> 16
//   "​16" -> rejected (U+200B is a format character, NOT whitespace)
export const PY_WHITESPACE_CODE_POINTS = [
  0x09, // HORIZONTAL TAB
  0x0a, // LINE FEED
  0x0b, // VERTICAL TAB
  0x0c, // FORM FEED
  0x0d, // CARRIAGE RETURN
  0x1c, // FILE SEPARATOR
  0x1d, // GROUP SEPARATOR
  0x1e, // RECORD SEPARATOR
  0x1f, // UNIT SEPARATOR
  0x20, // SPACE
  0x85, // NEXT LINE
  0xa0, // NO-BREAK SPACE
  0x1680, // OGHAM SPACE MARK
  0x2000, // EN QUAD
  0x2001, // EM QUAD
  0x2002, // EN SPACE
  0x2003, // EM SPACE
  0x2004, // THREE-PER-EM SPACE
  0x2005, // FOUR-PER-EM SPACE
  0x2006, // SIX-PER-EM SPACE
  0x2007, // FIGURE SPACE
  0x2008, // PUNCTUATION SPACE
  0x2009, // THIN SPACE
  0x200a, // HAIR SPACE
  0x2028, // LINE SEPARATOR
  0x2029, // PARAGRAPH SEPARATOR
  0x202f, // NARROW NO-BREAK SPACE
  0x205f, // MEDIUM MATHEMATICAL SPACE
  0x3000, // IDEOGRAPHIC SPACE
];

const WHITESPACE_SET = new Set(PY_WHITESPACE_CODE_POINTS);

/**
 * @param {number} cp code point
 * @returns {boolean}
 */
export function isPyWhitespace(cp) {
  return WHITESPACE_SET.has(cp);
}

// ---------------------------------------------------------------------------
// Unicode decimal digit table (MEASURED: fullwidth "１２" -> 12, Arabic-Indic "٣" -> 3)
// ---------------------------------------------------------------------------
// Every maximal run of General_Category=Nd code points, as [firstCodePoint, length].
// Unicode guarantees each script's digits 0-9 occupy 10 consecutive code points in
// ascending value order, so within a run the digit value is (cp - first) % 10.
// (Every run length below is a multiple of 10; U+1D7CE starts five adjacent
// mathematical-digit blocks, hence its length of 50.)
export const UNICODE_DECIMAL_DIGIT_RUNS = [
  [0x0030, 10], [0x0660, 10], [0x06f0, 10], [0x07c0, 10], [0x0966, 10],
  [0x09e6, 10], [0x0a66, 10], [0x0ae6, 10], [0x0b66, 10], [0x0be6, 10],
  [0x0c66, 10], [0x0ce6, 10], [0x0d66, 10], [0x0de6, 10], [0x0e50, 10],
  [0x0ed0, 10], [0x0f20, 10], [0x1040, 10], [0x1090, 10], [0x17e0, 10],
  [0x1810, 10], [0x1946, 10], [0x19d0, 10], [0x1a80, 10], [0x1a90, 10],
  [0x1b50, 10], [0x1bb0, 10], [0x1c40, 10], [0x1c50, 10], [0xa620, 10],
  [0xa8d0, 10], [0xa900, 10], [0xa9d0, 10], [0xa9f0, 10], [0xaa50, 10],
  [0xabf0, 10], [0xff10, 10], [0x104a0, 10], [0x10d30, 10], [0x11066, 10],
  [0x110f0, 10], [0x11136, 10], [0x111d0, 10], [0x112f0, 10], [0x11450, 10],
  [0x114d0, 10], [0x11650, 10], [0x116c0, 10], [0x11730, 10], [0x118e0, 10],
  [0x11950, 10], [0x11c50, 10], [0x11d50, 10], [0x11da0, 10], [0x11f50, 10],
  [0x16a60, 10], [0x16ac0, 10], [0x16b50, 10], [0x1d7ce, 50], [0x1e140, 10],
  [0x1e2f0, 10], [0x1e4f0, 10], [0x1e950, 10], [0x1fbf0, 10],
];

/**
 * Decimal value 0..9 of a Unicode decimal digit, or -1 if the code point is not
 * a decimal digit.
 * @param {number} cp code point
 * @returns {number}
 */
export function unicodeDigitValue(cp) {
  for (const [first, length] of UNICODE_DECIMAL_DIGIT_RUNS) {
    if (cp >= first && cp < first + length) {
      return (cp - first) % 10;
    }
  }
  return -1;
}

// ---------------------------------------------------------------------------
// Grammar table (MEASURED accept/reject list)
// ---------------------------------------------------------------------------
// int(s) for base 10 accepts, in order:
//   whitespace* [ '+' | '-' ] digit ( '_'? digit )* whitespace*
// with no other characters anywhere. Consequences, all measured:
//   accept: "16" "  16  " "\t42\n" "+16" "-5" "1_6" "016" "１２" "٣"
//   reject: "" "-" "0x10" "0b101" "1e5" "1.5" "abc" "1_" "_1" "1__2" "4 2" "- 5"
export const UNDERSCORE = 0x5f;
export const PLUS_SIGN = 0x2b;
export const MINUS_SIGN = 0x2d;

/**
 * Python's int(text) for base 10.
 * @param {string} text
 * @returns {{ok: true, value: bigint} | {ok: false}}
 */
export function pyIntFromString(text) {
  const cps = Array.from(text, (ch) => ch.codePointAt(0));

  let start = 0;
  let end = cps.length;
  while (start < end && isPyWhitespace(cps[start])) start += 1;
  while (end > start && isPyWhitespace(cps[end - 1])) end -= 1;

  let i = start;
  let negative = false;
  if (i < end && (cps[i] === PLUS_SIGN || cps[i] === MINUS_SIGN)) {
    negative = cps[i] === MINUS_SIGN;
    i += 1;
  }

  // At least one digit is required immediately after the optional sign: this is
  // what rejects "", "-", "_1" and "- 5".
  let value = 0n;
  let digitCount = 0;
  let previousWasUnderscore = false;

  while (i < end) {
    const cp = cps[i];
    if (cp === UNDERSCORE) {
      // An underscore is legal only strictly between two digits.
      if (digitCount === 0 || previousWasUnderscore) return { ok: false };
      previousWasUnderscore = true;
      i += 1;
      continue;
    }
    const digit = unicodeDigitValue(cp);
    if (digit < 0) return { ok: false };
    value = value * 10n + BigInt(digit);
    digitCount += 1;
    previousWasUnderscore = false;
    i += 1;
  }

  if (digitCount === 0) return { ok: false }; // no digits at all
  if (previousWasUnderscore) return { ok: false }; // trailing "_"

  return { ok: true, value: negative ? -value : value };
}

// lib/python/errors.mjs
//
// Python-side runtime services:
//   * process I/O shims for sys.stdout / sys.stderr
//   * SystemExit semantics (argparse's exit path)
//   * exception base class carrying a Python-style dotted type name
//   * traceback rendering, driven by an explicit frame table
//   * the MEASURED traceback template for this program's construct failure
//
// Nothing is exited with process.exit(): we only ever set process.exitCode and
// return, so pending stdout/stderr writes are always flushed by Node.

// ---------------------------------------------------------------------------
// sys.stdout / sys.stderr
// ---------------------------------------------------------------------------

/** @param {string} text */
export function writeStdout(text) {
  process.stdout.write(text);
}

/** @param {string} text */
export function writeStderr(text) {
  process.stderr.write(text);
}

/**
 * Python's print() for a single string argument.
 * @param {string} text
 */
export function print(text) {
  writeStdout(text + '\n');
}

// ---------------------------------------------------------------------------
// Script naming (argparse derives prog from basename(sys.argv[0]))
// ---------------------------------------------------------------------------

/**
 * basename() without importing node:path -- split on both separators.
 * @param {string} filePath
 * @returns {string}
 */
export function basename(filePath) {
  const parts = String(filePath).split(/[/\\]/);
  return parts[parts.length - 1] || String(filePath);
}

/**
 * The argparse `prog`: basename(process.argv[1]) -> "test3.mjs".
 * @param {string[]} [argv]
 * @returns {string}
 */
export function progName(argv = process.argv) {
  return basename(argv[1] ?? '');
}

/**
 * The script stem, i.e. prog with its final extension removed -> "test3".
 * Used for the traceback filename ("test3.py") and the PyInstaller error line
 * ("Failed to execute script 'test3'").
 * @param {string} [prog]
 * @returns {string}
 */
export function scriptStem(prog = progName()) {
  const dot = prog.lastIndexOf('.');
  return dot > 0 ? prog.slice(0, dot) : prog;
}

// ---------------------------------------------------------------------------
// SystemExit
// ---------------------------------------------------------------------------

/**
 * Python's SystemExit. Thrown by the parser's exit()/error() paths and caught by
 * the entry point, which turns it into process.exitCode.
 */
export class SystemExit extends Error {
  /** @param {number} code */
  constructor(code = 0) {
    super(`SystemExit: ${code}`);
    this.name = 'SystemExit';
    this.pyType = 'SystemExit';
    this.code = code;
  }
}

// ---------------------------------------------------------------------------
// Python-style exceptions
// ---------------------------------------------------------------------------

/**
 * Base for exceptions that must render as "<dotted.type>: <message>" inside a
 * traceback. `pyType` is the fully qualified name Python would print.
 */
export class PythonException extends Error {
  /**
   * @param {string} pyType e.g. 'construct.core.FormatFieldError'
   * @param {string} message may contain newlines
   */
  constructor(pyType, message) {
    super(message);
    this.name = pyType;
    this.pyType = pyType;
    this.pyMessage = message;
    /** @type {PythonException|null} the "during handling" predecessor */
    this.pyContext = null;
  }
}

/**
 * The header line Python prints for an exception: "<type>: <message>".
 * @param {{pyType: string, pyMessage: string}} exc
 * @returns {string}
 */
export function formatExceptionLine(exc) {
  return exc.pyMessage === '' ? exc.pyType : `${exc.pyType}: ${exc.pyMessage}`;
}

// ---------------------------------------------------------------------------
// Traceback rendering
// ---------------------------------------------------------------------------

export const TRACEBACK_HEADER = 'Traceback (most recent call last):';
export const CHAINED_CONTEXT_NOTE =
  'During handling of the above exception, another exception occurred:';

/**
 * One stack frame line: `  File "<file>", line <line>, in <func>`.
 *
 * Note: no source-text line is emitted. That matches the ground truth for the
 * frozen executable, whose linecache cannot find test3.py (it only prints source
 * text when a same-named .py file happens to sit in the current directory).
 *
 * @param {{file: string, line: number, func: string}} frame
 * @returns {string}
 */
export function formatFrame(frame) {
  return `  File "${frame.file}", line ${frame.line}, in ${frame.func}`;
}

/**
 * One traceback section: header, frames, then the exception line(s).
 * @param {{frames: Array<{file: string, line: number, func: string}>, exception: {pyType: string, pyMessage: string}}} section
 * @returns {string[]} lines
 */
export function formatTracebackSection(section) {
  return [
    TRACEBACK_HEADER,
    ...section.frames.map(formatFrame),
    ...formatExceptionLine(section.exception).split('\n'),
  ];
}

/**
 * A chained traceback. Sections are rendered oldest-first, separated by a blank
 * line, the "During handling ..." note, and another blank line -- exactly the
 * measured layout.
 * @param {Array<{frames: Array<object>, exception: object}>} sections
 * @returns {string} newline-terminated text
 */
export function formatTraceback(sections) {
  const lines = [];
  sections.forEach((section, index) => {
    if (index > 0) {
      lines.push('', CHAINED_CONTEXT_NOTE, '');
    }
    lines.push(...formatTracebackSection(section));
  });
  return lines.join('\n') + '\n';
}

// ---------------------------------------------------------------------------
// PyInstaller bootloader failure line
// ---------------------------------------------------------------------------
// MEASURED: "[PYI-338:ERROR] Failed to execute script 'test3' due to unhandled
// exception!" -- the number is the live process id, so it is taken from
// process.pid rather than hardcoded.

/**
 * @param {string} stem script stem, e.g. 'test3'
 * @param {number} [pid]
 * @returns {string}
 */
export function pyiFailureLine(stem, pid = process.pid) {
  return `[PYI-${pid}:ERROR] Failed to execute script '${stem}' due to unhandled exception!`;
}

// ---------------------------------------------------------------------------
// MEASURED traceback template for the construct build failure
// ---------------------------------------------------------------------------
// Reading top to bottom, this reproduces the ground-truth stderr for
// `--a 256 --b 0` verbatim (only the PYI process id varies):
//
//   Traceback (most recent call last):
//     File "construct/core.py", line 1165, in _build
//   struct.error: 'B' format requires 0 <= number <= 255
//
//   During handling of the above exception, another exception occurred:
//
//   Traceback (most recent call last):
//     File "test3.py", line 19, in <module>
//     File "test3.py", line 15, in main
//     File "construct/core.py", line 452, in build
//     File "construct/core.py", line 464, in build_stream
//     File "construct/core.py", line 2260, in _build
//     File "construct/core.py", line 2774, in _build
//     File "construct/core.py", line 1167, in _build
//   construct.core.FormatFieldError: Error in path (building) -> field1
//   struct '<B' error during building, given value 256
//   [PYI-<pid>:ERROR] Failed to execute script 'test3' due to unhandled exception!

/** Frames of the inner struct.error section. */
export const STRUCT_ERROR_FRAMES = [
  { file: 'construct/core.py', line: 1165, func: '_build' },
];

/**
 * Frames of the outer FormatFieldError section. The two test3.py frames use the
 * script stem so the filename tracks the real entry point instead of being
 * hardcoded; their line numbers come from the Python source
 * (line 19 = `main()`, line 15 = the `struct_format.build(...)` call).
 * @param {string} stem
 * @returns {Array<{file: string, line: number, func: string}>}
 */
export function formatFieldErrorFrames(stem) {
  const scriptPy = `${stem}.py`;
  return [
    { file: scriptPy, line: 19, func: '<module>' },
    { file: scriptPy, line: 15, func: 'main' },
    { file: 'construct/core.py', line: 452, func: 'build' },
    { file: 'construct/core.py', line: 464, func: 'build_stream' },
    { file: 'construct/core.py', line: 2260, func: '_build' },
    { file: 'construct/core.py', line: 2774, func: '_build' },
    { file: 'construct/core.py', line: 1167, func: '_build' },
  ];
}

/**
 * Render the full unhandled-exception report for a construct build failure:
 * chained traceback plus the PyInstaller bootloader line.
 * @param {{pyType: string, pyMessage: string, pyContext: object|null}} exception the FormatFieldError
 * @param {string} stem script stem, e.g. 'test3'
 * @returns {string} newline-terminated text destined for stderr
 */
export function formatUnhandledBuildException(exception, stem) {
  const sections = [];
  if (exception.pyContext) {
    sections.push({
      frames: STRUCT_ERROR_FRAMES,
      exception: exception.pyContext,
    });
  }
  sections.push({
    frames: formatFieldErrorFrames(stem),
    exception,
  });
  return formatTraceback(sections) + pyiFailureLine(stem) + '\n';
}

// lib/construct/errors.mjs
//
// The construct exception surface, plus Python's low-level struct.error.
//
// Rendered names are the dotted paths Python prints in a traceback:
//   struct.error
//   construct.core.ConstructError
//   construct.core.FormatFieldError

import { PythonException } from '../python/errors.mjs';

/**
 * Python's `struct.error`, raised by struct.pack() when a value does not fit the
 * format character. This is the *inner* exception of the measured chain.
 */
export class StructError extends PythonException {
  /** @param {string} message */
  constructor(message) {
    super('struct.error', message);
  }
}

/**
 * construct's base error.
 *
 * construct prepends the build path to the message exactly like this:
 *   message = "Error in path {}\n".format(path) + message
 * so `Error in path (building) -> field1\nstruct '<B' error ...` is one message
 * spanning two rendered lines.
 */
export class ConstructError extends PythonException {
  /**
   * @param {string} pyType dotted Python type name
   * @param {string} message
   * @param {string|null} path e.g. '(building) -> field1'
   */
  constructor(pyType, message = '', path = null) {
    super(pyType, path === null ? message : `Error in path ${path}\n${message}`);
    this.path = path;
  }
}

/** Raised by FormatField when the packer rejects the value. */
export class FormatFieldError extends ConstructError {
  /**
   * @param {string} message
   * @param {string|null} path
