  constructor(message, path = null) {
    super('construct.core.FormatFieldError', message, path);
  }
}

// lib/construct/format_field.mjs
//
// FormatField: a fixed-width number packed with a Python struct format string.
// Only the pieces the source program uses are implemented, but the packing rule
// and the range table are written out explicitly so they are auditable.
//
// Values arrive as BigInt (see lib/python/int_parse.mjs) and the produced byte
// sequence is a PLAIN Array of integers 0..255.

import { StructError, FormatFieldError } from './errors.mjs';

// ---------------------------------------------------------------------------
// struct format character table (MEASURED error text for 'B')
// ---------------------------------------------------------------------------
// `rangeError` is verbatim what CPython's struct module raises:
//   struct.error: 'B' format requires 0 <= number <= 255
export const STRUCT_FORMAT_TABLE = {
  B: {
    byteCount: 1,
    signed: false,
    min: 0n,
    max: 255n,
    rangeError: "'B' format requires 0 <= number <= 255",
  },
};

/**
 * Little-endian packing of an unsigned integer into `byteCount` bytes: byte i is
 * the i-th base-256 digit, least significant first. For a single byte this is
 * simply [value], which is why Int8ul and Int8ub produce identical output.
 * @param {bigint} value already range-checked
 * @param {number} byteCount
 * @returns {number[]}
 */
export function packUnsignedLittleEndian(value, byteCount) {
  const out = [];
  let rest = value;
  for (let i = 0; i < byteCount; i += 1) {
    out.push(Number(rest % 256n));
    rest = rest / 256n;
  }
  return out;
}

/**
 * Base class for every construct subcon that can build bytes.
 */
export class Subcon {
  /**
   * @param {string} name construct's class-ish name, used only for diagnostics
   */
  constructor(name) {
    this.name = name;
  }

  /**
   * @param {bigint} _value
   * @param {string} _path
   * @returns {number[]}
   */
  build(_value, _path) {
    throw new Error('Subcon.build is abstract');
  }

  /**
   * The JS stand-in for Python's `"fieldName" / subcon` renaming operator.
   * See lib/construct/struct.mjs for the free-function form, `field()`.
   * @param {string} fieldName
   */
  named(fieldName) {
    // Imported lazily-by-reference to keep this module free of a cycle at load
    // time; Renamed only needs to exist by the time named() is called.
    return new RenamedRef.Renamed(fieldName, this);
  }
}

// Filled in by lib/construct/struct.mjs to avoid a circular import at load time.
export const RenamedRef = { Renamed: null };

/**
 * A number field described by a Python struct format string such as '<B'.
 */
export class FormatField extends Subcon {
  /**
   * @param {string} fmtstr Python struct format, e.g. '<B'
   * @param {string} formatChar the format character, e.g. 'B'
   * @param {'little'|'big'} endianness
   */
  constructor(fmtstr, formatChar, endianness = 'little') {
    super('FormatField');
    this.fmtstr = fmtstr;
    this.formatChar = formatChar;
    this.endianness = endianness;
    this.spec = STRUCT_FORMAT_TABLE[formatChar];
    if (!this.spec) {
      throw new Error(`unsupported struct format character: ${formatChar}`);
    }
    this.sizeof = this.spec.byteCount;
  }

  /**
   * struct.pack(this.fmtstr, value).
   * @param {bigint} value
   * @returns {number[]}
   * @throws {StructError} when the value is out of range
   */
  pack(value) {
    const { min, max, rangeError, byteCount } = this.spec;
    if (value < min || value > max) {
      throw new StructError(rangeError);
    }
    const bytes = packUnsignedLittleEndian(value, byteCount);
    return this.endianness === 'little' ? bytes : bytes.reverse();
  }

  /**
   * construct's FormatField._build: pack, and on any packer failure re-raise as a
   * FormatFieldError carrying the build path. The original struct.error is kept
   * as `pyContext` so the traceback can render the "During handling of the above
   * exception" chain.
   *
   * MEASURED message: `struct '<B' error during building, given value 256`
   * (Python's `"struct %r error during building, given value %r"`; %r of the
   * format string adds the single quotes, %r of an int is its decimal digits).
   *
   * @param {bigint} value
   * @param {string} path e.g. '(building) -> field1'
   * @returns {number[]}
   */
  build(value, path) {
    try {
      return this.pack(value);
    } catch (cause) {
      const error = new FormatFieldError(
        `struct '${this.fmtstr}' error during building, given value ${value}`,
        path,
      );
      error.pyContext = cause;
      throw error;
    }
  }
}

/** construct.Int8ul -- unsigned 8-bit, little endian ('<B'). */
export const Int8ul = new FormatField('<B', 'B', 'little');

/** construct.Int8ub -- unsigned 8-bit, big endian ('>B'); identical output. */
export const Int8ub = new FormatField('>B', 'B', 'big');

// lib/construct/struct.mjs
//
// The Struct combinator plus the JS stand-in for construct's `"name" / subcon`
// renaming operator.
//
// JavaScript has no operator overloading, so the Python
//     "field1" / construct.Int8ul
// is written either as
//     field('field1', construct.Int8ul)      // free function, reads left-to-right
// or as
//     construct.Int8ul.named('field1')       // method form
// Both produce the same Renamed wrapper.

import { Subcon, RenamedRef } from './format_field.mjs';

/** construct's build path root. MEASURED: "Error in path (building) -> field1". */
export const BUILD_PATH_ROOT = '(building)';

/** How construct extends a path when descending into a named member. */
export function extendPath(path, memberName) {
  return `${path} -> ${memberName}`;
}

/**
 * construct's Renamed: a subcon that knows the field name it is bound to.
 */
export class Renamed extends Subcon {
  /**
   * @param {string} fieldName
   * @param {Subcon} subcon
   */
  constructor(fieldName, subcon) {
    super('Renamed');
    this.fieldName = fieldName;
    this.subcon = subcon;
  }

  /**
   * @param {bigint} value
   * @param {string} path
   * @returns {number[]}
   */
  build(value, path) {
    return this.subcon.build(value, path);
  }
}

// Close the loop for Subcon.prototype.named() without a load-time import cycle.
RenamedRef.Renamed = Renamed;

/**
 * The `"name" / subcon` equivalent.
 * @param {string} fieldName
 * @param {Subcon} subcon
 * @returns {Renamed}
 */
export function field(fieldName, subcon) {
  return new Renamed(fieldName, subcon);
}

/** Alias, for readers who prefer the noun. */
export const named = field;

/**
 * A sequence of named subcons built in declaration order.
 */
export class StructConstruct extends Subcon {
  /** @param {Renamed[]} members */
  constructor(members) {
    super('Struct');
    this.members = members;
  }

  /**
   * construct's Struct._build. Members are built strictly in declaration order
   * and the first failure aborts, which is why `--a 256 --b 0` reports field1 and
   * `--a 1 --b 256` reports field2.
   *
   * @param {Record<string, bigint>} obj mapping of field name -> value
   * @param {string} [path]
   * @returns {number[]} plain array of bytes 0..255
   */
  build(obj, path = BUILD_PATH_ROOT) {
    const out = [];
    for (const member of this.members) {
      const value = obj[member.fieldName];
      const bytes = member.build(value, extendPath(path, member.fieldName));
      for (const b of bytes) out.push(b);
    }
    return out;
  }
}

/**
 * construct.Struct(...)
 * @param {...Renamed} members
 * @returns {StructConstruct}
 */
export function Struct(...members) {
  return new StructConstruct(members);
}

