export { StructError, ConstructError, FormatFieldError } from './errors.mjs';

// lib/cli/argument_parser.mjs
//
// A hand-rolled argparse clone, built by hand from process.argv. Every user-visible
// string comes from the ARGPARSE_MESSAGES catalogue below, and every branching
// decision comes from one of the explicit tables/predicates, so each behaviour can
// be checked against the measured ground truth line by line.
//
// Reproduced behaviours (all measured against the reference build):
//   usage/help layout and the "options:" heading
//   required-argument errors, and that they fire BEFORE unrecognized-argument errors
//   type-conversion errors at consume time (left to right, before required checks)
//   -h/--help anywhere wins immediately, unless an earlier token already failed
//   long-option abbreviation (--h, --he, --hel all mean --help)
//   "--opt=value", last-occurrence-wins, negative numbers accepted as values
//   a bare "--" and everything after it becomes unrecognized input
//   "-hx" fires -h then rejects the tail; "--help=x" is an explicit-argument error

import { pyStrRepr } from '../python/bytes_repr.mjs';
import { pyIntFromString } from '../python/int_parse.mjs';
import { SystemExit, progName, writeStdout, writeStderr } from '../python/errors.mjs';

// ---------------------------------------------------------------------------
// Message catalogue (MEASURED, verbatim)
// ---------------------------------------------------------------------------
export const ARGPARSE_MESSAGES = {
  /** "the following arguments are required: --a, --b" */
  requiredArguments: (names) =>
    `the following arguments are required: ${names.join(', ')}`,
  /** "invalid int value: 'abc'" (Python's %r of the raw string) */
  invalidValue: (typeName, raw) =>
    `invalid ${typeName} value: ${pyStrRepr(raw)}`,
  /** "expected one argument" */
  expectedOneArgument: () => 'expected one argument',
  /** "unrecognized arguments: --c 3" */
  unrecognizedArguments: (tokens) =>
    `unrecognized arguments: ${tokens.join(' ')}`,
  /** "ambiguous option: --x could match --help, --a" */
  ambiguousOption: (token, optionStrings) =>
    `ambiguous option: ${token} could match ${optionStrings.join(', ')}`,
  /** "ignored explicit argument 'x'" */
  ignoredExplicitArgument: (explicitArg) =>
    `ignored explicit argument ${pyStrRepr(explicitArg)}`,
  /** wrapper argparse puts around per-action errors */
  argumentError: (actionName, message) => `argument ${actionName}: ${message}`,
};

/** Exit codes, per the spec. */
export const EXIT_CODES = { ok: 0, argparseError: 2 };

// ---------------------------------------------------------------------------
// Type registry ("type=int" in the Python source)
// ---------------------------------------------------------------------------
export const TYPE_REGISTRY = {
  int: { name: 'int', convert: pyIntFromString },
};

// ---------------------------------------------------------------------------
// Token classification tables
// ---------------------------------------------------------------------------
// argparse's `_negative_number_matcher`. Python's `\d` is Unicode-aware, hence
// \p{Nd} here rather than [0-9]. A token matching this is treated as a value (not
// an option) as long as the parser declares no negative-number-like options --
// which is why `--a -5` reaches construct with -5.
export const NEGATIVE_NUMBER_RE = /^-[\p{Nd}]+$|^-[\p{Nd}]*\.[\p{Nd}]+$/u;

/** The token that ends option processing outright. */
export const OPTION_TERMINATOR = '--';

/** Help-layout constants, matching argparse's HelpFormatter. */
export const HELP_LAYOUT = { indent: 2, gap: 2, maxHelpPosition: 24 };

/**
 * argparse's `_get_action_name` for options: all option strings joined by "/".
 * "--a" for --a, "-h/--help" for the help action.
 * @param {object} action
 * @returns {string}
 */
export function actionName(action) {
  return action.optionStrings.join('/');
}

/**
 * Internal signal for a per-action failure. parseArgs() converts it into the
 * "argument <name>: <message>" wrapper and then into a usage error.
 */
class ArgumentError extends Error {
  constructor(action, message) {
    super(ARGPARSE_MESSAGES.argumentError(actionName(action), message));
    this.name = 'ArgumentError';
  }
}

export class ArgumentParser {
  /**
   * @param {{prog?: string, addHelp?: boolean}} [options]
   */
  constructor(options = {}) {
    this.prog = options.prog ?? progName();
    this.prefixChars = '-';
    this.allowAbbrev = true;
    /** @type {object[]} declaration order drives usage, help and build order */
    this.actions = [];
    /** @type {Map<string, object>} insertion order drives ambiguity reporting */
    this.optionStringActions = new Map();

    if (options.addHelp !== false) {
      this.addArgument(['-h', '--help'], {
        action: 'help',
        help: 'show this help message and exit',
      });
    }
  }

  /**
   * parser.add_argument(...)
   * @param {string|string[]} flags e.g. '--a' or ['-h', '--help']
   * @param {{action?: 'store'|'help', type?: string, required?: boolean, metavar?: string, help?: string}} [spec]
   */
  addArgument(flags, spec = {}) {
    const optionStrings = Array.isArray(flags) ? flags.slice() : [flags];
    const longest = optionStrings.find((s) => s.startsWith('--')) ?? optionStrings[0];
    const dest = longest.replace(/^-+/, '').replace(/-/g, '_');
    const kind = spec.action ?? 'store';
    const action = {
      optionStrings,
      dest,
      kind,
      // nargs is 0 for flags (help) and 1 for value-taking options.
      nargs: kind === 'help' ? 0 : 1,
      metavar: spec.metavar ?? dest.toUpperCase(),
      typeName: spec.type ?? null,
      required: spec.required ?? false,
      help: spec.help ?? '',
    };
    this.actions.push(action);
    for (const optionString of optionStrings) {
      this.optionStringActions.set(optionString, action);
    }
    return action;
  }

  // -------------------------------------------------------------------------
  // Usage / help
  // -------------------------------------------------------------------------

  /** @returns {string} newline-terminated "usage: ..." line */
  formatUsage() {
    const parts = this.actions.map((action) => {
      const head = action.optionStrings[0];
      const core = action.nargs === 0 ? head : `${head} ${action.metavar}`;
      return action.required ? core : `[${core}]`;
    });
    const tail = parts.length > 0 ? ' ' + parts.join(' ') : '';
    return `usage: ${this.prog}${tail}\n`;
  }

  /**
   * The invocation column of the help table: "-h, --help", "--a A".
   * @param {object} action
   * @returns {string}
   */
  formatInvocation(action) {
    if (action.nargs === 0) return action.optionStrings.join(', ');
    return action.optionStrings.map((s) => `${s} ${action.metavar}`).join(', ');
  }

  /** @returns {string} newline-terminated full help text */
  formatHelp() {
    const { indent, gap, maxHelpPosition } = HELP_LAYOUT;
    const invocations = this.actions.map((a) => this.formatInvocation(a));
    const widest = invocations.reduce((m, s) => Math.max(m, s.length), 0);
    // argparse: help_position = min(action_max_length + 2, max_help_position),
    // where action_max_length already includes the current indent.
    const helpPosition = Math.min(widest + indent + gap, maxHelpPosition);

    const lines = [this.formatUsage().replace(/\n$/, ''), '', 'options:'];
    this.actions.forEach((action, index) => {
      const invocation = invocations[index];
      const prefix = ' '.repeat(indent) + invocation;
      if (!action.help) {
        lines.push(prefix);
        return;
      }
      const pad = helpPosition - indent - invocation.length;
      if (pad > 0) {
        lines.push(prefix + ' '.repeat(pad) + action.help);
      } else {
        lines.push(prefix);
        lines.push(' '.repeat(helpPosition) + action.help);
      }
    });
    return lines.join('\n') + '\n';
  }

  // -------------------------------------------------------------------------
  // Exit paths
  // -------------------------------------------------------------------------

  /**
   * parser.error(): usage plus "<prog>: error: <message>" on stderr, exit 2.
   * @param {string} message
   * @returns {never}
   */
  error(message) {
    writeStderr(this.formatUsage());
    writeStderr(`${this.prog}: error: ${message}\n`);
    throw new SystemExit(EXIT_CODES.argparseError);
  }

  /**
   * The help action: full help on stdout, exit 0.
   * @returns {never}
   */
  printHelpAndExit() {
    writeStdout(this.formatHelp());
    throw new SystemExit(EXIT_CODES.ok);
  }

  // -------------------------------------------------------------------------
  // Token classification (argparse's _parse_optional / _get_option_tuples)
  // -------------------------------------------------------------------------

  /**
   * @param {string} token
   * @returns {Array<{action: object, optionString: string, explicitArg: string|null}>}
   */
  getOptionTuples(token) {
    const chars = this.prefixChars;
    const result = [];
    const isPrefix = (ch) => ch !== undefined && chars.includes(ch);

    if (isPrefix(token[0]) && isPrefix(token[1])) {
      // Long option: match by prefix when abbreviation is allowed.
      if (!this.allowAbbrev) return result;
      let optionPrefix = token;
      let explicitArg = null;
      const eq = token.indexOf('=');
      if (eq !== -1) {
        optionPrefix = token.slice(0, eq);
        explicitArg = token.slice(eq + 1);
      }
      for (const [optionString, action] of this.optionStringActions) {
        if (optionString.startsWith(optionPrefix)) {
          result.push({ action, optionString, explicitArg });
        }
      }
    } else if (isPrefix(token[0]) && !isPrefix(token[1])) {
      // Short option, possibly with its argument glued on: "-hx".
      const shortPrefix = token.slice(0, 2);
      const shortExplicitArg = token.slice(2);
      for (const [optionString, action] of this.optionStringActions) {
        if (optionString === shortPrefix) {
          result.push({ action, optionString, explicitArg: shortExplicitArg });
        } else if (optionString.startsWith(token)) {
          result.push({ action, optionString, explicitArg: null });
        }
      }
    }
    return result;
  }

  /**
   * argparse's _parse_optional. Returns null when the token is meant to be
   * positional input, otherwise a tuple whose `action` is null for an option that
   * looks like one but is not declared.
   * @param {string} token
   * @returns {{action: object|null, optionString: string, explicitArg: string|null}|null}
   */
  parseOptional(token) {
    if (token === '') return null; // empty string -> positional
    if (!this.prefixChars.includes(token[0])) return null; // no prefix -> positional

    const exact = this.optionStringActions.get(token);
    if (exact) return { action: exact, optionString: token, explicitArg: null };

    if (token.length === 1) return null; // a bare "-" is positional

    const eq = token.indexOf('=');
    if (eq !== -1) {
      const head = token.slice(0, eq);
      const known = this.optionStringActions.get(head);
      if (known) {
        return { action: known, optionString: head, explicitArg: token.slice(eq + 1) };
      }
    }

    const tuples = this.getOptionTuples(token);
    if (tuples.length > 1) {
      this.error(
        ARGPARSE_MESSAGES.ambiguousOption(
          token,
          tuples.map((t) => t.optionString),
        ),
      );
    }
    if (tuples.length === 1) return tuples[0];

    // Looks like a negative number and we have no such options -> positional.
    if (NEGATIVE_NUMBER_RE.test(token)) return null;
    // Contains a space -> positional (this is what accepts "- 5" as a value).
    if (token.includes(' ')) return null;

    return { action: null, optionString: token, explicitArg: null };
  }

  /**
   * True when a token can NOT serve as an option's value. That is any token
   * argparse classifies as an option ('O') or as the "--" separator ('-'); only
   * plain positional tokens ('A') are eligible, because for optionals argparse
   * strips the "-*" wildcards out of the nargs pattern.
   * @param {string|undefined} token
   * @returns {boolean}
   */
  looksLikeOption(token) {
    if (token === undefined) return true;
    if (token === OPTION_TERMINATOR) return true;
    return this.parseOptional(token) !== null;
  }

  // -------------------------------------------------------------------------
  // Value conversion and action dispatch
  // -------------------------------------------------------------------------

  /**
   * @param {object} action
   * @param {string} raw
   * @returns {bigint|string}
   */
  convertValue(action, raw) {
    if (!action.typeName) return raw;
    const type = TYPE_REGISTRY[action.typeName];
    const converted = type.convert(raw);
    if (!converted.ok) {
      throw new ArgumentError(
        action,
        ARGPARSE_MESSAGES.invalidValue(type.name, raw),
      );
    }
    return converted.value;
  }

  /**
   * @param {object} action
   * @param {string[]} values
   * @param {Record<string, unknown>} namespace
   * @param {Set<object>} seen
   */
  takeAction(action, values, namespace, seen) {
    seen.add(action);
    if (action.kind === 'help') {
      this.printHelpAndExit();
    }
    // 'store': the last occurrence wins, matching "--a 1 --b 1 --a 5" -> 5.
    namespace[action.dest] = this.convertValue(action, values[0]);
  }

  // -------------------------------------------------------------------------
  // Main loop
  // -------------------------------------------------------------------------

  /**
   * @param {string[]} argv
   * @returns {{namespace: Record<string, unknown>, extras: string[]}}
   */
  parseKnownArgs(argv) {
    /** @type {Record<string, unknown>} */
    const namespace = {};
    for (const action of this.actions) {
      if (action.kind === 'store') namespace[action.dest] = null;
    }
    /** @type {Set<object>} */
    const seen = new Set();
    /** @type {string[]} */
    const extras = [];

    let index = 0;
    while (index < argv.length) {
      const token = argv[index];

      // MEASURED: the "--" itself is NOT swallowed. It and every following token
      // become positional input, and since this parser declares no positionals
      // they all end up in the unrecognized list.
      if (token === OPTION_TERMINATOR) {
        for (let k = index; k < argv.length; k += 1) extras.push(argv[k]);
        break;
      }

      const optional = this.parseOptional(token);
      if (optional === null || optional.action === null) {
        extras.push(token); // positional input, or an undeclared option
        index += 1;
        continue;
      }

      index = this.consumeOptional(optional, argv, index, namespace, seen, extras);
    }

    return { namespace, extras, seen };
  }

  /**
   * Consume one option (and any glued-on short options), returning the next index.
   * @returns {number}
   */
  consumeOptional(optional, argv, index, namespace, seen, extras) {
    let action = optional.action;
    let optionString = optional.optionString;
    let explicitArg = optional.explicitArg;

    for (;;) {
      if (explicitArg !== null) {
        const isShort = !this.prefixChars.includes(optionString[1]);
        if (action.nargs === 0 && isShort && explicitArg !== '') {
          // "-hx": fire -h now, then re-interpret "-x" as the next short option.
          this.takeAction(action, [], namespace, seen);
          const prefixChar = optionString[0];
          const nextOptionString = prefixChar + explicitArg[0];
          const nextAction = this.optionStringActions.get(nextOptionString);
          if (nextAction) {
            action = nextAction;
            optionString = nextOptionString;
            explicitArg = explicitArg.slice(1);
            continue;
          }
          extras.push(prefixChar + explicitArg);
          return index + 1;
        }
        if (action.nargs === 1) {
          // "--a=16", and "--a=" which yields the empty string.
          this.takeAction(action, [explicitArg], namespace, seen);
          return index + 1;
        }
        // "--help=x": a flag cannot take a value.
        throw new ArgumentError(
          action,
          ARGPARSE_MESSAGES.ignoredExplicitArgument(explicitArg),
        );
      }

      if (action.nargs === 0) {
        this.takeAction(action, [], namespace, seen);
        return index + 1;
      }

      const next = argv[index + 1];
      if (this.looksLikeOption(next)) {
        throw new ArgumentError(action, ARGPARSE_MESSAGES.expectedOneArgument());
      }
      this.takeAction(action, [next], namespace, seen);
      return index + 2;
    }
  }

  /**
   * parser.parse_args(). Throws SystemExit for help and for every error path.
   * @param {string[]} [argv] defaults to process.argv.slice(2)
   * @returns {Record<string, unknown>}
   */
  parseArgs(argv = process.argv.slice(2)) {
    let result;
    try {
      result = this.parseKnownArgs(argv);
    } catch (err) {
      if (err instanceof ArgumentError) this.error(err.message);
      throw err;
    }

    // MEASURED ordering: required-argument errors come first, which is why
    // "-- --a 1 --b 1" reports missing --a/--b rather than unrecognized input.
    const missing = this.actions
      .filter((action) => action.required && !result.seen.has(action))
      .map((action) => actionName(action));
    if (missing.length > 0) {
      this.error(ARGPARSE_MESSAGES.requiredArguments(missing));
    }

    if (result.extras.length > 0) {
      this.error(ARGPARSE_MESSAGES.unrecognizedArguments(result.extras));
    }

    return result.namespace;
  }
}

