import { ArgumentParser } from './lib/cli/argument_parser.mjs';
import * as construct from './lib/construct/index.mjs';
import { pyBytesRepr } from './lib/python/bytes_repr.mjs';
import {
  SystemExit,
  formatUnhandledBuildException,
  print,
  progName,
  scriptStem,
  writeStderr,
} from './lib/python/errors.mjs';
import { ConstructError } from './lib/construct/errors.mjs';

function main() {
  const parser = new ArgumentParser();
  parser.addArgument('--a', { type: 'int', required: true });
  parser.addArgument('--b', { type: 'int', required: true });
  const args = parser.parseArgs();

  const structFormat = construct.Struct(
    construct.field('field1', construct.Int8ul), // define first field
    construct.field('field2', construct.Int8ul), // define second field
  );
  const data = structFormat.build({ field1: args.a, field2: args.b });
